@page "/chat"
@namespace sv_84cfca62f6b542f8b0dc3a3fc0e05909.Components.Pages.Chat
@rendermode InteractiveServer
@inject Services.IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@ActiveChannelName"
                 ChannelDescription="@ActiveChannelDescription"
                 Messages="_messages"
                 ThreadSummaries="_threadSummaries"
                 IsLoadingMore="_isLoadingMore"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage"
                 OnLoadMore="LoadOlderMessages"
                 class="@(_threadOpen ? "" : "expanded")" />

    @if (_threadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Services.Channel> _channels = [];
    private List<Services.Message> _messages = [];
    private List<Services.ThreadSummary> _threadSummaries = [];
    private int _activeChannelId;
    private bool _isLoadingMore;
    private const int PageSize = 30;

    // Thread state
    private bool _threadOpen;
    private Services.Message? _threadRootMessage;
    private List<Services.Message> _threadReplies = [];

    private string ActiveChannelName =>
        _channels.FirstOrDefault(c => c.Id == _activeChannelId)?.Name ?? "";

    private string ActiveChannelDescription =>
        _channels.FirstOrDefault(c => c.Id == _activeChannelId)?.Description ?? "";

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0]);
        }
    }

    private async Task SelectChannel(Services.Channel channel)
    {
        _activeChannelId = channel.Id;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _threadSummaries = BuildThreadSummaries(_messages);
        CloseThread();
        await ChatService.MarkChannelReadAsync(channel.Id);
        _channels = await ChatService.GetChannelsAsync(); // refresh unread counts
    }

    private async Task LoadOlderMessages()
    {
        if (_isLoadingMore) return;
        _isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messages.Count, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _threadSummaries = BuildThreadSummaries(_messages);
        }
        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
        _threadSummaries = BuildThreadSummaries(_messages);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to reflect new reaction
        _messages = await ChatService.GetMessagesAsync(_activeChannelId, 0, _messages.Count);
    }

    private static List<Services.ThreadSummary> BuildThreadSummaries(List<Services.Message> messages)
    {
        return messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new Services.ThreadSummary(
                g.Key,
                g.Count(),
                g.Max(m => m.SentAt)))
            .ToList();
    }
}

