toolArgs.file_text:
.chat-layout {
    display: flex;
    height: calc(100vh - 4rem);
    overflow: hidden;
}

/* Channel Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2b2d31;
    color: #b5bac1;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #1e1f22;
}

.sidebar-title {
    padding: 1rem;
    margin: 0;
    font-size: 1rem;
    color: #f2f3f5;
    border-bottom: 1px solid #1e1f22;
}

.channel-list {
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 0.5rem 1rem;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    gap: 0.125rem;
    position: relative;
    border-radius: 4px;
    margin: 2px 8px;
}

.channel-item:hover {
    background: #35373c;
}

.channel-item.active {
    background: #404249;
    color: #f2f3f5;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
}

.channel-description {
    font-size: 0.75rem;
    opacity: 0.7;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 0.75rem;
    top: 50%;
    transform: translateY(-50%);
    background: #f23f43;
    color: white;
    font-size: 0.7rem;
    font-weight: 700;
    border-radius: 8px;
    padding: 0.125rem 0.4rem;
    min-width: 1rem;
    text-align: center;
}

/* Message Area */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #313338;
    color: #dbdee1;
    min-width: 0;
}

.message-area.expanded {
    flex: 1;
}

.message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    flex-shrink: 0;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1rem;
    color: #f2f3f5;
}

.message-area-header p {
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
    opacity: 0.7;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.loading-indicator {
    text-align: center;
    padding: 0.5rem;
    font-size: 0.8rem;
    opacity: 0.6;
}

/* Message Bubble */
.message-bubble {
    padding: 0.5rem 1rem;
    border-radius: 4px;
    position: relative;
}

.message-bubble:hover {
    background: #2e3035;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

.message-author {
    font-weight: 600;
    font-size: 0.9rem;
    color: #f2f3f5;
}

.message-time {
    font-size: 0.7rem;
    opacity: 0.5;
}

.message-content {
    margin-top: 0.25rem;
    font-size: 0.9rem;
    line-height: 1.4;
    word-break: break-word;
}

.message-reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.25rem;
    margin-top: 0.375rem;
}

.reaction-badge {
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.125rem 0.375rem;
    font-size: 0.8rem;
    cursor: pointer;
    color: #dbdee1;
}

.reaction-badge:hover {
    border-color: #5865f2;
    background: #3b3d44;
}

.thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.25rem 0;
    font-weight: 600;
}

.thread-link:hover {
    text-decoration: underline;
}

/* Hover actions */
.message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.125rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.125rem;
}

.action-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.25rem 0.375rem;
    border-radius: 3px;
    font-size: 0.9rem;
}

.action-btn:hover {
    background: #3b3d44;
}

.emoji-picker {
    position: absolute;
    top: -2.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 6px;
    padding: 0.375rem;
    z-index: 10;
}

.emoji-option {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1.1rem;
    padding: 0.25rem;
    border-radius: 3px;
}

.emoji-option:hover {
    background: #3b3d44;
}

/* Message Input */
.message-input-area {
    padding: 0.75rem 1rem;
    border-top: 1px solid #3f4147;
    display: flex;
    gap: 0.5rem;
    align-items: flex-end;
    flex-shrink: 0;
}

.message-textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    color: #dbdee1;
    padding: 0.625rem 1rem;
    font-size: 0.9rem;
    resize: none;
    min-height: 2.5rem;
    max-height: 8rem;
    font-family: inherit;
    outline: none;
}

.message-textarea:focus {
    box-shadow: 0 0 0 1px #5865f2;
}

.send-btn {
    background: #5865f2;
    color: white;
    border: none;
    border-radius: 6px;
    padding: 0.5rem 1rem;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
.thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2b2d31;
    color: #dbdee1;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #1e1f22;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #f2f3f5;
}

.close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.25rem 0.5rem;
    border-radius: 3px;
}

.close-btn:hover {
    background: #3b3d44;
    color: #f2f3f5;
}

.thread-root-message {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    background: #232428;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem;
}

.thread-reply {
    padding: 0.5rem;
    border-radius: 4px;
}

.thread-reply:hover {
    background: #2e3035;
}

.thread-input-area {
    padding: 0.75rem 1rem;
    border-top: 1px solid #3f4147;
    display: flex;
    gap: 0.5rem;
    align-items: flex-end;
    flex-shrink: 0;
}

